/**
 * Static asset manifest.
 *
 * Single source of truth for paths to local assets under `public/`.
 * Components MUST NOT hardcode `"/brand/logo-mark.svg"` etc.; import from
 * here so renames or restructures stay one-edit operations.
 *
 * Remote URLs (CDN) are NOT listed here — those flow through `lib/cdn.ts`
 * (`resolveCdnUrl`) so the CDN host is interchangeable.
 *
 * Placeholder images are generated by `pnpm gen:placeholders` into
 * `public/placeholders/`; new SVGs for the brand land in `public/brand/`.
 */

/* ===== Brand ===== */

/**
 * Hawkr logo lockups (from `brand/hawkr/`) — rendered on every navbar and
 * footer. `mark` is the stall icon only; `horizontal` includes the wordmark.
 */
export const brandAssets = {
	logoHorizontal: "/brand/logo-horizontal.svg",
	/** Wheat-cream variant (Figma 17:245), used in dark mode. */
	logoHorizontalLight: "/brand/logo-horizontal-light.svg",
	logoMark: "/brand/logo-mark.svg",
	/** Monochrome Hawkr mark (awning + H) — fills with `currentColor` plus an
	 * embedded `prefers-color-scheme: dark` media query so the same file
	 * works for both the OS-driven favicon and inline use. Used by the
	 * login modal + favicon. */
	logoGrass: "/brand/logo-grass.svg",
	/** Hawkr wordmark (`brand/hawkr/hawkr-wordmark.svg`). Used by the
	 * initial loader, where it colour-wipes in from left to right. */
	wordmark: "/brand/wordmark.svg",
} as const;

/* ===== Defaults ===== */

/** Placeholder shown while a post image is loading or absent. */
export const placeholders = {
	post: "/placeholders/post.svg",
	buyerAvatar: "/placeholders/avatar.svg",
} as const;

/* ===== Type-safe accessors ===== */

export type BrandAssetKey = keyof typeof brandAssets;
